    case permanent // = 1
    case unauthenticated // = 2
    case updateRequired // = 3
    case conflict // = 4
    case invalid // = 5
    case UNRECOGNIZED(Int)

    public init() {
      self = .transient
    }

    public init?(rawValue: Int) {
      switch rawValue {
      case 0: self = .transient
      case 1: self = .permanent
      case 2: self = .unauthenticated
      case 3: self = .updateRequired
      case 4: self = .conflict
      case 5: self = .invalid
      default: self = .UNRECOGNIZED(rawValue)
      }
    }

    public var rawValue: Int {
      switch self {
      case .transient: return 0
      case .permanent: return 1
      case .unauthenticated: return 2
      case .updateRequired: return 3
      case .conflict: return 4
      case .invalid: return 5
      case .UNRECOGNIZED(let i): return i
      }
    }

    // The compiler won't synthesize support with the UNRECOGNIZED case.
    public static let allCases: [ClientFailure.Kind] = [
      .transient,
      .permanent,
      .unauthenticated,
      .updateRequired,
      .conflict,
      .invalid,
    ]

