/// One line of a unified diff, numbered on both sides.
public nonisolated struct ClientDiffRow: Sendable {
  // SwiftProtobuf.Message conformance is added in an extension below. See the
  // `Message` and `Message+*Additions` files in the SwiftProtobuf library for
  // methods supported on all messages.

  public var id: Int32 = 0

  public var kind: ClientDiffRow.Kind = .header

  public var text: String = String()

  /// 0 when the side has no line.
  public var oldLine: Int32 = 0

  public var newLine: Int32 = 0

  public var unknownFields = SwiftProtobuf.UnknownStorage()

  public nonisolated enum Kind: SwiftProtobuf.Enum, Swift.CaseIterable {
    public typealias RawValue = Int
    case header // = 0
    case hunk // = 1
    case context // = 2
    case addition // = 3
    case deletion // = 4
    case UNRECOGNIZED(Int)

    public init() {
      self = .header
    }

    public init?(rawValue: Int) {
      switch rawValue {
      case 0: self = .header
      case 1: self = .hunk
      case 2: self = .context
      case 3: self = .addition
      case 4: self = .deletion
      default: self = .UNRECOGNIZED(rawValue)
      }
    }

    public var rawValue: Int {
      switch self {
      case .header: return 0
      case .hunk: return 1
      case .context: return 2
      case .addition: return 3
      case .deletion: return 4
      case .UNRECOGNIZED(let i): return i
      }
    }

    // The compiler won't synthesize support with the UNRECOGNIZED case.
    public static let allCases: [ClientDiffRow.Kind] = [
      .header,
      .hunk,
      .context,
      .addition,
      .deletion,
    ]

  }

  public init() {}
}

